insert into public.colecciones (id, tipo, datos, orden, activo) values ('f9109345-9887-5421-a3d9-417e5d368bd3', 'preguntas', '{"tema": "reservas", "pregunta": "¿Cómo se paga la reserva?", "respuesta": "Con un anticipo por transferencia o Nequi para confirmar; el saldo se paga al llegar. El porcentaje del anticipo lo confirma la finca."}'::jsonb, 0, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('1279df9d-0520-59a8-89a9-41c3ddd27f1d', 'preguntas', '{"tema": "reservas", "pregunta": "¿Puedo cancelar o cambiar la fecha?", "respuesta": "Por definir: la política de cancelación y cambios la publica la finca desde el panel."}'::jsonb, 1, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('82ef6907-d32d-511c-860f-622f1e222a65', 'preguntas', '{"tema": "reservas", "pregunta": "¿Los precios incluyen impuestos?", "respuesta": "Sí. Las tarifas por noche incluyen el impuesto y el seguro hotelero."}'::jsonb, 2, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('86d76cb4-7afd-5296-8a48-64d9cd49272b', 'preguntas', '{"tema": "reservas", "pregunta": "¿Por qué reservar directo?", "respuesta": "Porque no pagas comisiones de terceros y hablas directamente con la finca."}'::jsonb, 3, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('8187f74c-b5c4-5e8e-82ee-860c661d5c1b', 'preguntas', '{"tema": "estadia", "pregunta": "¿A qué hora es la entrada y la salida?", "respuesta": "La entrada es desde las 3:00 p. m. La hora de salida la confirma la finca."}'::jsonb, 4, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('08714eac-0014-5225-bc50-a2a412cc1588', 'preguntas', '{"tema": "estadia", "pregunta": "¿Cuál es el horario del jacuzzi?", "respuesta": "El jacuzzi es climatizado y funciona de 5:00 a 10:00 p. m. todos los días."}'::jsonb, 5, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('441f957b-76b4-5b0c-82fc-27539663aa6a', 'preguntas', '{"tema": "estadia", "pregunta": "¿El desayuno está incluido?", "respuesta": "Es opcional: cuesta $12.000 adicionales por persona y se pide al reservar."}'::jsonb, 6, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('56c57268-7ef1-5b39-ad23-e1131d5567b0', 'preguntas', '{"tema": "estadia", "pregunta": "¿Podemos cocinar?", "respuesta": "Sí. El kiosco tiene cocina y asador para que el grupo prepare sus comidas."}'::jsonb, 7, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('f0177b0f-060b-549d-9c9d-96bf6580ce92', 'preguntas', '{"tema": "mascotas", "pregunta": "¿Puedo ir con mi mascota?", "respuesta": "Sí. Las mascotas son bienvenidas sin costo adicional; avísanos al reservar."}'::jsonb, 8, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('85f67857-1386-5c40-96f3-0c6cc8401fdf', 'preguntas', '{"tema": "mascotas", "pregunta": "¿Pueden ir niños?", "respuesta": "Sí. Los menores de edad deben llegar acompañados por sus padres y con su documento de identidad."}'::jsonb, 9, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('83cd4d46-f52e-59b6-8278-28b4dd2ddca4', 'preguntas', '{"tema": "eventos", "pregunta": "¿Puedo celebrar un evento?", "respuesta": "Sí. Usa el cotizador de la página de eventos o escríbenos con la fecha y el número de personas."}'::jsonb, 10, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('c6ce5a58-7af8-58a5-a5b2-7bc33b15cbd6', 'preguntas', '{"tema": "eventos", "pregunta": "¿Qué incluye el pasadía?", "respuesta": "Uso de las zonas sociales de 9:00 a. m. a 5:00 p. m. por $22.000 por persona más el seguro, con un mínimo de 10 personas."}'::jsonb, 11, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('532b8e0e-3cd7-5646-8df7-a0c2ab655f39', 'preguntas', '{"tema": "eventos", "pregunta": "¿Cuántas personas caben con la finca completa?", "respuesta": "Hasta 40 personas en las 14 habitaciones, por $2.800.000 la noche (solo alojamiento)."}'::jsonb, 12, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('3cfdac0a-1fa6-5466-8691-cfb6e455d2eb', 'preguntas', '{"tema": "llegada", "pregunta": "¿Cómo llego desde el aeropuerto?", "respuesta": "El aeropuerto El Edén está a unos 22 a 27 km. Pasa por Armenia y toma la vía a Circasia hasta el kilómetro 3, frente al Retorno Colillas."}'::jsonb, 13, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('80d363d3-d853-5313-b7dc-685576c1f64e', 'preguntas', '{"tema": "llegada", "pregunta": "¿Hay parqueadero?", "respuesta": "Sí, dentro de la finca y sin costo para huéspedes."}'::jsonb, 14, true) on conflict (id) do nothing;
insert into public.colecciones (id, tipo, datos, orden, activo) values ('4ab2bc6f-60c3-58c9-828d-14b59e50ff4f', 'preguntas', '{"tema": "llegada", "pregunta": "¿Hay wifi?", "respuesta": "Sí. La cobertura la confirma la finca."}'::jsonb, 15, true) on conflict (id) do nothing;
